package s3api

import (
	"context"
	"errors"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/gorilla/mux"
	iamlib "github.com/seaweedfs/seaweedfs/weed/iam"
	"github.com/seaweedfs/seaweedfs/weed/s3api/s3_constants"
	"github.com/stretchr/testify/require"
)

func TestObjectLockRoutesUseDedicatedActions(t *testing.T) {
	bindings := handlerActionBindings(t)
	for _, tc := range []struct{ handler, want string }{
		{"GetObjectRetentionHandler", "ACTION_GET_OBJECT_RETENTION"},
		{"PutObjectRetentionHandler", "ACTION_PUT_OBJECT_RETENTION"},
		{"GetObjectLegalHoldHandler", "ACTION_GET_OBJECT_LEGAL_HOLD"},
		{"PutObjectLegalHoldHandler", "ACTION_PUT_OBJECT_LEGAL_HOLD"},
		{"GetObjectLockConfigurationHandler", "ACTION_GET_BUCKET_OBJECT_LOCK_CONFIG"},
		{"PutObjectLockConfigurationHandler", "ACTION_PUT_BUCKET_OBJECT_LOCK_CONFIG"},
	} {
		if got := bindings[tc.handler]; got != tc.want {
			t.Errorf("%s is gated on %s, want %s", tc.handler, got, tc.want)
		}
	}
}

func TestGovernanceBypassUsesDedicatedAuthorization(t *testing.T) {
	for _, tc := range []struct {
		name    string
		action  Action
		allowed bool
	}{
		{"dedicated permission", Action(s3_constants.ACTION_BYPASS_GOVERNANCE_RETENTION + ":test-bucket/*"), true},
		{"coarse write", Action(s3_constants.ACTION_WRITE + ":test-bucket/*"), false},
		{"admin", Action(s3_constants.ACTION_ADMIN), true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			iam := newTestIAM()
			iam.identities[0].Actions = []Action{tc.action}
			iam.identities[0].Account = &Account{Id: "test-account"}
			s3a := &S3ApiServer{iam: iam}
			req := httptest.NewRequest(http.MethodDelete, "http://localhost:8333/test-bucket/test-object", nil)
			req = mux.SetURLVars(req, map[string]string{"bucket": "test-bucket", "object": "test-object"})
			require.NoError(t, signRawHTTPRequest(context.Background(), req,
				"AKIAIOSFODNN7EXAMPLE", "wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY", "us-east-1"))

			if got := s3a.checkGovernanceBypassPermission(req, "test-bucket", "/test-object"); got != tc.allowed {
				t.Errorf("checkGovernanceBypassPermission() = %v, want %v", got, tc.allowed)
			}
		})
	}
}

// The bypass check authorizes against a synthetic request shaped like the
// real one; DELETE ?versionId used to re-resolve to s3:DeleteObjectVersion,
// so the delete-version grant silently satisfied the bypass check.
func TestGovernanceBypassDoesNotInheritDeleteObjectVersion(t *testing.T) {
	iam := &IdentityAccessManagement{}
	require.NoError(t, iam.PutPolicy("DeleteVersions",
		`{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Action":["s3:DeleteObject","s3:DeleteObjectVersion"],"Resource":"arn:aws:s3:::worm/*"}]}`))
	require.NoError(t, iam.PutPolicy("BypassGovernance",
		`{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Action":["s3:DeleteObject","s3:DeleteObjectVersion","s3:BypassGovernanceRetention"],"Resource":"arn:aws:s3:::worm/*"}]}`))
	s3a := &S3ApiServer{iam: iam}

	req := httptest.NewRequest(http.MethodDelete, "http://localhost:8333/worm/doc.txt?versionId=abc123", nil)
	req = mux.SetURLVars(req, map[string]string{"bucket": "worm", "object": "doc.txt"})

	req = req.WithContext(s3_constants.SetIdentityInContext(req.Context(), &Identity{
		Name:        "deleter",
		PolicyNames: []string{"DeleteVersions"},
		Account:     &Account{Id: "test-account"},
	}))
	if s3a.checkGovernanceBypassPermission(req, "worm", "/doc.txt") {
		t.Fatal("s3:DeleteObjectVersion alone satisfied the governance bypass check")
	}

	req = req.WithContext(s3_constants.SetIdentityInContext(req.Context(), &Identity{
		Name:        "breaker",
		PolicyNames: []string{"BypassGovernance"},
		Account:     &Account{Id: "test-account"},
	}))
	if !s3a.checkGovernanceBypassPermission(req, "worm", "/doc.txt") {
		t.Fatal("s3:BypassGovernanceRetention did not satisfy the governance bypass check")
	}
}

// The object-lock request headers on PutObject/CreateMultipartUpload must be
// authorized as s3:PutObjectRetention / s3:PutObjectLegalHold; s3:PutObject
// alone used to set retention and legal hold on new versions.
func TestObjectLockHeadersRequireDedicatedActions(t *testing.T) {
	iam := &IdentityAccessManagement{isAuthEnabled: true}
	require.NoError(t, iam.PutPolicy("Writer",
		`{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Action":["s3:PutObject"],"Resource":"arn:aws:s3:::worm/*"}]}`))
	require.NoError(t, iam.PutPolicy("Locked",
		`{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Action":["s3:PutObject","s3:PutObjectRetention","s3:PutObjectLegalHold"],"Resource":"arn:aws:s3:::worm/*"}]}`))
	s3a := &S3ApiServer{iam: iam}

	retainUntil := time.Now().Add(24 * time.Hour).Format(time.RFC3339)
	for _, tc := range []struct {
		name    string
		policy  string
		headers map[string]string
		wantErr error
	}{
		{"writer sets retention", "Writer",
			map[string]string{s3_constants.AmzObjectLockMode: "COMPLIANCE", s3_constants.AmzObjectLockRetainUntilDate: retainUntil},
			ErrObjectLockNotAuthorized},
		{"writer sets legal hold", "Writer",
			map[string]string{s3_constants.AmzObjectLockLegalHold: s3_constants.LegalHoldOn},
			ErrObjectLockNotAuthorized},
		{"writer plain put", "Writer", nil, nil},
		{"locked principal sets both", "Locked",
			map[string]string{s3_constants.AmzObjectLockMode: "GOVERNANCE", s3_constants.AmzObjectLockRetainUntilDate: retainUntil, s3_constants.AmzObjectLockLegalHold: s3_constants.LegalHoldOn},
			nil},
	} {
		t.Run(tc.name, func(t *testing.T) {
			req := httptest.NewRequest(http.MethodPut, "http://localhost:8333/worm/doc.txt", nil)
			req = mux.SetURLVars(req, map[string]string{"bucket": "worm", "object": "doc.txt"})
			for k, v := range tc.headers {
				req.Header.Set(k, v)
			}
			req = req.WithContext(s3_constants.SetIdentityInContext(req.Context(), &Identity{
				Name:        "caller",
				PolicyNames: []string{tc.policy},
				Account:     &Account{Id: "test-account"},
			}))
			if err := s3a.validateObjectLockHeaders(req, "worm", "doc.txt", true); !errors.Is(err, tc.wantErr) {
				t.Errorf("validateObjectLockHeaders() = %v, want %v", err, tc.wantErr)
			}
		})
	}
}

func TestGovernanceBypassUsesBodyObjectKey(t *testing.T) {
	iam := newTestIAM()
	iam.identities[0].Actions = []Action{
		Action(s3_constants.ACTION_BYPASS_GOVERNANCE_RETENTION + ":test-bucket/allowed/*"),
	}
	iam.identities[0].Account = &Account{Id: "test-account"}
	s3a := &S3ApiServer{iam: iam}

	req := httptest.NewRequest(http.MethodPost, "http://localhost:8333/test-bucket?delete", nil)
	req = mux.SetURLVars(req, map[string]string{"bucket": "test-bucket"})
	req = req.WithContext(s3_constants.SetIdentityInContext(req.Context(), iam.identities[0]))

	if !s3a.checkGovernanceBypassPermission(req, "test-bucket", "allowed/object") {
		t.Fatal("object-scoped bypass grant did not authorize a DeleteObjects body key")
	}
	if s3a.checkGovernanceBypassPermission(req, "test-bucket", "denied/object") {
		t.Fatal("object-scoped bypass grant authorized a key outside its prefix")
	}
}

func TestGovernanceBypassNormalizesBodyObjectKey(t *testing.T) {
	iam := newTestIAM()
	iam.identities[0].Account = &Account{Id: "test-account"}
	s3a := &S3ApiServer{iam: iam}

	req := httptest.NewRequest(http.MethodPost, "http://localhost:8333/test-bucket?delete", nil)
	req = mux.SetURLVars(req, map[string]string{"bucket": "test-bucket"})
	req = req.WithContext(s3_constants.SetIdentityInContext(req.Context(), iam.identities[0]))

	iam.identities[0].Actions = []Action{
		Action(s3_constants.ACTION_BYPASS_GOVERNANCE_RETENTION + ":test-bucket/allowed/o?ject"),
	}
	if !s3a.checkGovernanceBypassPermission(req, "test-bucket", "//allowed//object") {
		t.Fatal("canonical object grant did not authorize the equivalent noncanonical body key")
	}

	iam.identities[0].Actions = []Action{
		Action(s3_constants.ACTION_BYPASS_GOVERNANCE_RETENTION + ":test-bucket/allowed//o?ject"),
	}
	if s3a.checkGovernanceBypassPermission(req, "test-bucket", "//allowed//object") {
		t.Fatal("noncanonical alias grant authorized the canonical mutation target")
	}
}

func TestCoarseReadWriteDoNotGrantObjectLockActions(t *testing.T) {
	identity := &Identity{
		Name: "object-reader-writer",
		Actions: []Action{
			Action(s3_constants.ACTION_READ + ":test-bucket"),
			Action(s3_constants.ACTION_WRITE + ":test-bucket"),
		},
	}

	for _, action := range []string{
		s3_constants.ACTION_GET_OBJECT_RETENTION,
		s3_constants.ACTION_PUT_OBJECT_RETENTION,
		s3_constants.ACTION_GET_OBJECT_LEGAL_HOLD,
		s3_constants.ACTION_PUT_OBJECT_LEGAL_HOLD,
		s3_constants.ACTION_GET_BUCKET_OBJECT_LOCK_CONFIG,
		s3_constants.ACTION_PUT_BUCKET_OBJECT_LOCK_CONFIG,
		s3_constants.ACTION_BYPASS_GOVERNANCE_RETENTION,
	} {
		if identity.CanDo(Action(action), "test-bucket", "some/key") {
			t.Errorf("coarse Read/Write unexpectedly granted %s", action)
		}
	}
}

func TestObjectLockActionsRoundTrip(t *testing.T) {
	for _, tc := range []struct{ policyAction, identityAction string }{
		{"GetObjectRetention", s3_constants.ACTION_GET_OBJECT_RETENTION},
		{"PutObjectRetention", s3_constants.ACTION_PUT_OBJECT_RETENTION},
		{"GetObjectLegalHold", s3_constants.ACTION_GET_OBJECT_LEGAL_HOLD},
		{"PutObjectLegalHold", s3_constants.ACTION_PUT_OBJECT_LEGAL_HOLD},
		{"GetBucketObjectLockConfiguration", s3_constants.ACTION_GET_BUCKET_OBJECT_LOCK_CONFIG},
		{"PutBucketObjectLockConfiguration", s3_constants.ACTION_PUT_BUCKET_OBJECT_LOCK_CONFIG},
		{"BypassGovernanceRetention", s3_constants.ACTION_BYPASS_GOVERNANCE_RETENTION},
	} {
		t.Run(tc.policyAction, func(t *testing.T) {
			for _, action := range []string{tc.policyAction, "s3:" + tc.policyAction} {
				if got := iamlib.MapToStatementAction(action); got != tc.identityAction {
					t.Errorf("MapToStatementAction(%q) = %q, want %q", action, got, tc.identityAction)
				}
			}
			if got := iamlib.MapToIdentitiesAction(tc.identityAction); got != tc.policyAction {
				t.Errorf("MapToIdentitiesAction(%q) = %q, want %q", tc.identityAction, got, tc.policyAction)
			}
		})
	}
}

package s3api

import (
	"net/http"
	"net/url"
	"strings"
	"testing"

	"github.com/seaweedfs/seaweedfs/weed/s3api/s3_constants"
	"github.com/stretchr/testify/assert"
)

// createTestRequestWithQueryParams creates a test HTTP request with query parameters
// and extracts bucket/object from the path. This helper reduces duplication in test setup.
func createTestRequestWithQueryParams(method, path string, queryParams map[string]string) (*http.Request, string, string, error) {
	// Parse the URL
	u, err := url.Parse(path)
	if err != nil {
		return nil, "", "", err
	}

	// Add query parameters
	q := u.Query()
	for k, v := range queryParams {
		q.Add(k, v)
	}
	u.RawQuery = q.Encode()

	// Create HTTP request
	req, err := http.NewRequest(method, u.String(), nil)
	if err != nil {
		return nil, "", "", err
	}

	// Parse path to extract bucket and object
	parts := strings.Split(strings.TrimPrefix(u.Path, "/"), "/")
	bucket := ""
	object := ""
	if len(parts) > 0 {
		bucket = parts[0]
	}
	if len(parts) > 1 {
		object = "/" + strings.Join(parts[1:], "/")
	}

	return req, bucket, object, nil
}

// TestGranularActionMappingSecurity demonstrates how the new granular action mapping
// fixes critical security issues that existed with the previous coarse mapping
func TestGranularActionMappingSecurity(t *testing.T) {
	tests := []struct {
		name                  string
		method                string
		bucket                string
		objectKey             string
		queryParams           map[string]string
		description           string
		problemWithOldMapping string
		granularActionResult  string
	}{
		{
			name:        "delete_object_security_fix",
			method:      "DELETE",
			bucket:      "sensitive-bucket",
			objectKey:   "confidential-file.txt",
			queryParams: map[string]string{},
			description: "DELETE object operations should map to s3:DeleteObject, not s3:PutObject",
			problemWithOldMapping: "Old mapping incorrectly mapped DELETE object to s3:PutObject, " +
				"allowing users with only PUT permissions to delete objects - a critical security flaw",
			granularActionResult: "s3:DeleteObject",
		},
		{
			name:        "get_object_acl_precision",
			method:      "GET",
			bucket:      "secure-bucket",
			objectKey:   "private-file.pdf",
			queryParams: map[string]string{"acl": ""},
			description: "GET object ACL should map to s3:GetObjectAcl, not generic s3:GetObject",
			problemWithOldMapping: "Old mapping would allow users with s3:GetObject permission to " +
				"read ACLs, potentially exposing sensitive permission information",
			granularActionResult: "s3:GetObjectAcl",
		},
		{
			name:        "put_object_tagging_precision",
			method:      "PUT",
			bucket:      "data-bucket",
			objectKey:   "business-document.xlsx",
			queryParams: map[string]string{"tagging": ""},
			description: "PUT object tagging should map to s3:PutObjectTagging, not generic s3:PutObject",
			problemWithOldMapping: "Old mapping couldn't distinguish between actual object uploads and " +
				"metadata operations like tagging, making fine-grained permissions impossible",
			granularActionResult: "s3:PutObjectTagging",
		},
		{
			name:        "multipart_upload_precision",
			method:      "POST",
			bucket:      "large-files",
			objectKey:   "video.mp4",
			queryParams: map[string]string{"uploads": ""},
			description: "Multipart upload initiation should map to s3:CreateMultipartUpload",
			problemWithOldMapping: "Old mapping would treat multipart operations as generic s3:PutObject, " +
				"preventing policies that allow regular uploads but restrict large multipart operations",
			granularActionResult: "s3:CreateMultipartUpload",
		},
		{
			name:        "bucket_policy_vs_bucket_creation",
			method:      "PUT",
			bucket:      "corporate-bucket",
			objectKey:   "",
			queryParams: map[string]string{"policy": ""},
			description: "Bucket policy modifications should map to s3:PutBucketPolicy, not s3:CreateBucket",
			problemWithOldMapping: "Old mapping couldn't distinguish between creating buckets and " +
				"modifying bucket policies, potentially allowing unauthorized policy changes",
			granularActionResult: "s3:PutBucketPolicy",
		},
		{
			name:        "list_vs_read_distinction",
			method:      "GET",
			bucket:      "inventory-bucket",
			objectKey:   "",
			queryParams: map[string]string{"uploads": ""},
			description: "Listing multipart uploads should map to s3:ListBucketMultipartUploads",
			problemWithOldMapping: "Old mapping would use generic s3:ListBucket for all bucket operations, " +
				"preventing fine-grained control over who can see ongoing multipart operations",
			granularActionResult: "s3:ListBucketMultipartUploads",
		},
		{
			name:        "delete_object_tagging_precision",
			method:      "DELETE",
			bucket:      "metadata-bucket",
			objectKey:   "tagged-file.json",
			queryParams: map[string]string{"tagging": ""},
			description: "Delete object tagging should map to s3:DeleteObjectTagging, not s3:DeleteObject",
			problemWithOldMapping: "Old mapping couldn't distinguish between deleting objects and " +
				"deleting tags, preventing policies that allow tag management but not object deletion",
			granularActionResult: "s3:DeleteObjectTagging",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Create HTTP request with query parameters
			req := &http.Request{
				Method: tt.method,
				URL:    &url.URL{Path: "/" + tt.bucket + "/" + tt.objectKey},
			}

			// Add query parameters
			query := req.URL.Query()
			for key, value := range tt.queryParams {
				query.Set(key, value)
			}
			req.URL.RawQuery = query.Encode()

			// Test the granular action determination
			result := ResolveS3Action(req, string(s3_constants.ACTION_WRITE), tt.bucket, tt.objectKey)

			assert.Equal(t, tt.granularActionResult, result,
				"Security Fix Test: %s\n"+
					"Description: %s\n"+
					"Problem with old mapping: %s\n"+
					"Expected: %s, Got: %s",
				tt.name, tt.description, tt.problemWithOldMapping, tt.granularActionResult, result)

			// Log the security improvement
			t.Logf("SECURITY IMPROVEMENT: %s", tt.description)
			t.Logf("   Problem Fixed: %s", tt.problemWithOldMapping)
			t.Logf("   Granular Action: %s", result)
		})
	}
}

// TestBackwardCompatibilityFallback tests that the new system maintains backward compatibility
// with existing generic actions while providing enhanced granularity
func TestBackwardCompatibilityFallback(t *testing.T) {
	tests := []struct {
		name           string
		method         string
		bucket         string
		objectKey      string
		fallbackAction Action
		expectedResult string
		description    string
	}{
		{
			name:           "generic_read_fallback",
			method:         "GET", // Generic method without specific query params
			bucket:         "",    // Edge case: no bucket specified
			objectKey:      "",    // Edge case: no object specified
			fallbackAction: s3_constants.ACTION_READ,
			expectedResult: "s3:GetObject",
			description:    "Generic read operations should fall back to s3:GetObject for compatibility",
		},
		{
			name:           "generic_write_fallback",
			method:         "PUT", // Generic method without specific query params
			bucket:         "",    // Edge case: no bucket specified
			objectKey:      "",    // Edge case: no object specified
			fallbackAction: s3_constants.ACTION_WRITE,
			expectedResult: "s3:PutObject",
			description:    "Generic write operations should fall back to s3:PutObject for compatibility",
		},
		{
			name:           "already_granular_passthrough",
			method:         "GET",
			bucket:         "",
			objectKey:      "",
			fallbackAction: "s3:GetBucketLocation", // Already specific
			expectedResult: "s3:GetBucketLocation",
			description:    "Already granular actions should pass through unchanged",
		},
		{
			name:           "unknown_action_conversion",
			method:         "GET",
			bucket:         "",
			objectKey:      "",
			fallbackAction: "CustomAction", // Not S3-prefixed
			expectedResult: "s3:CustomAction",
			description:    "Unknown actions should be converted to S3 format for consistency",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req := &http.Request{
				Method: tt.method,
				URL:    &url.URL{Path: "/" + tt.bucket + "/" + tt.objectKey},
			}

			result := ResolveS3Action(req, string(tt.fallbackAction), tt.bucket, tt.objectKey)

			assert.Equal(t, tt.expectedResult, result,
				"Backward Compatibility Test: %s\nDescription: %s\nExpected: %s, Got: %s",
				tt.name, tt.description, tt.expectedResult, result)

			t.Logf("COMPATIBILITY: %s - %s", tt.description, result)
		})
	}
}

// TestPolicyEnforcementScenarios demonstrates how granular actions enable
// more precise and secure IAM policy enforcement
func TestPolicyEnforcementScenarios(t *testing.T) {
	scenarios := []struct {
		name            string
		policyExample   string
		method          string
		bucket          string
		objectKey       string
		queryParams     map[string]string
		expectedAction  string
		securityBenefit string
	}{
		{
			name: "allow_read_deny_acl_access",
			policyExample: `{
				"Version": "2012-10-17",
				"Statement": [
					{
						"Effect": "Allow",
						"Action": "s3:GetObject",
						"Resource": "arn:aws:s3:::sensitive-bucket/*"
					}
				]
			}`,
			method:          "GET",
			bucket:          "sensitive-bucket",
			objectKey:       "document.pdf",
			queryParams:     map[string]string{"acl": ""},
			expectedAction:  "s3:GetObjectAcl",
			securityBenefit: "Policy allows reading objects but denies ACL access - granular actions enable this distinction",
		},
		{
			name: "allow_tagging_deny_object_modification",
			policyExample: `{
				"Version": "2012-10-17",
				"Statement": [
					{
						"Effect": "Allow", 
						"Action": ["s3:PutObjectTagging", "s3:DeleteObjectTagging"],
						"Resource": "arn:aws:s3:::data-bucket/*"
					}
				]
			}`,
			method:          "PUT",
			bucket:          "data-bucket",
			objectKey:       "metadata-file.json",
			queryParams:     map[string]string{"tagging": ""},
			expectedAction:  "s3:PutObjectTagging",
			securityBenefit: "Policy allows tag management but prevents actual object uploads - critical for metadata-only roles",
		},
		{
			name: "restrict_multipart_uploads",
			policyExample: `{
				"Version": "2012-10-17",
				"Statement": [
					{
						"Effect": "Allow",
						"Action": "s3:PutObject",
						"Resource": "arn:aws:s3:::uploads/*"
					},
					{
						"Effect": "Deny",
						"Action": ["s3:CreateMultipartUpload", "s3:UploadPart"],
						"Resource": "arn:aws:s3:::uploads/*"
					}
				]
			}`,
			method:          "POST",
			bucket:          "uploads",
			objectKey:       "large-file.zip",
			queryParams:     map[string]string{"uploads": ""},
			expectedAction:  "s3:CreateMultipartUpload",
			securityBenefit: "Policy allows regular uploads but blocks large multipart uploads - prevents resource abuse",
		},
	}

	for _, scenario := range scenarios {
		t.Run(scenario.name, func(t *testing.T) {
			req := &http.Request{
				Method: scenario.method,
				URL:    &url.URL{Path: "/" + scenario.bucket + "/" + scenario.objectKey},
			}

			query := req.URL.Query()
			for key, value := range scenario.queryParams {
				query.Set(key, value)
			}
			req.URL.RawQuery = query.Encode()

			result := ResolveS3Action(req, string(s3_constants.ACTION_WRITE), scenario.bucket, scenario.objectKey)

			assert.Equal(t, scenario.expectedAction, result,
				"Policy Enforcement Scenario: %s\nExpected Action: %s, Got: %s",
				scenario.name, scenario.expectedAction, result)

			t.Logf("SECURITY SCENARIO: %s", scenario.name)
			t.Logf("   Expected Action: %s", result)
			t.Logf("   Security Benefit: %s", scenario.securityBenefit)
			t.Logf("   Policy Example:\n%s", scenario.policyExample)
		})
	}
}

// TestDeleteObjectPolicyEnforcement demonstrates that the architectural limitation has been fixed
// Previously, DeleteObject operations were mapped to s3:PutObject, preventing fine-grained policies from working
func TestDeleteObjectPolicyEnforcement(t *testing.T) {
	tests := []struct {
		name             string
		method           string
		bucket           string
		objectKey        string
		baseAction       Action
		expectedS3Action string
		policyScenario   string
	}{
		{
			name:             "delete_object_maps_to_correct_action",
			method:           http.MethodDelete,
			bucket:           "test-bucket",
