					"Expected: %s, Got: %s",
				tt.name, tt.method, tt.baseAction, tt.policyScenario, tt.expectedS3Action, result)

			t.Logf("ARCHITECTURAL FIX VERIFIED: %s", tt.name)
			t.Logf("   Method: %s -> S3 Action: %s", tt.method, result)
